import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    cpu_data = []
    if platform.system() == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["top", "-bn1"]
    end_time = time.time() + duration
    while time.time() < end_time:
        timestamp = time.time()
        output = subprocess.check_output(cmd, shell=platform.system() == "Windows")
        if platform.system() == "Windows":
            cpu_percent = float(output.decode().split("\n")[1].strip())
        else:
            cpu_line = output.decode().split("\n")[2]
            cpu_percent = float(cpu_line.split(",")[0].split(":")[1].strip().rstrip("% id"))
        cpu_data.append({"timestamp": timestamp, "cpu_percent": cpu_percent})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(cpu_data, f)
        return LOGFILE_PATH
    except IOError:
        return None

