import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    results = {}
    for ip in network:
        try:
            output = subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], capture_output=True, text=True, timeout=1)
            results[str(ip)] = output.returncode == 0
        except subprocess.CalledProcessError as e:
            raise e
    return results

import os
import glob
import subprocess
def task_func(directory, backup_dir='/path/to/backup'):
    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory '{directory}' does not exist")
    logs = glob.glob(os.path.join(directory, '**', '* cf.log'), recursive=True)
    if not logs:
        return 'No logs found to backup'
    os.makedirs(backup_dir, exist_ok=True)
    backup_file = os.path.join(backup_dir, 'logs_backup.tar.gz')
    subprocess.run(['tar', '-czf', backup_file] + logs, check=True)
    for log in logs:
        os.remove(log)
    return os.path.abspath(backup_file)

import subprocess
import platform
import time

def task_func(url):
    system = platform.system()
    if system == "Windows":
        cmd = f'start /B "" {url}'
    elif system == "Darwin":
        cmd = f'open {url} &'
    else:
        cmd = f'xdg-open {url} &'
    process = subprocess.Popen(cmd, shell=True)
    time.sleep(0.5)
    return process.poll()

