import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder) or not os.path.isdir(dst_folder):
        return {'success': False, 'message': 'Invalid source or destination folder', 'failed_files': []}
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        try:
            subprocess.Popen(['gzip', '-f', file_path])
            gz_file = file_path + '.gz'
            if os.path.exists(gz_file):
                shutil.move(gz_file, dst_folder)
        except Exception:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to process'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import pandas as pd
import matplotlib.pyplot as plt

def task_func(script_path, output_file_path):
    result = subprocess.run(['python', script_path], capture_output=True, text=True)
    if result.returncode != 0:
        raise ValueError("Script execution failed")
    try:
        df = pd.read_csv(output_file_path)
    except Exception as e:
        raise ValueError("Invalid CSV file")
    if len(df.columns) != 2:
        raise ValueError("CSV must have exactly 2 columns")
    ax = df.plot.bar(x=df.columns[0], y=df.columns[1], legend=False)
    return df, ax

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script path does not exist")
    proc = subprocess.Popen(['bash', script_path])
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    while proc.poll() is None and (time.time() - start_time) < timeout:
        try:
            p = psutil.Process(proc.pid)
            cpu_usage += p.cpu_percent(interval=0.1)
            mem_usage += p.memory_info().rss
        except psutil.NoSuchProcess:
            break
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
